from typing import List

class Solution:
    def findRestaurant(self, list1: List[str], list2: List[str]) -> List[str]:
        # Build index map for list2
        idx2 = {name: i for i, name in enumerate(list2)}
        common = []
        for i, name in enumerate(list1):
            if name in idx2:
                common.append([i + idx2[name], name])
        if not common:
            return []
        # Sort by total index sum
        common.sort(key=lambda x: x[0])
        min_sum = common[0][0]
        # Collect all names with the minimal sum
        return [name for sum_val, name in common if sum_val == min_sum]

