class Solution:
    def canPlaceFlowers(self, flowerbed: List[int], n: int) -> bool:
        # Pad the array to simplify edge handling
        flowerbed = [0] + flowerbed + [0]
        for i in range(1, len(flowerbed) - 1):
            # If the current spot and its neighbors are empty, plant a flower
            if flowerbed[i] == 0 and flowerbed[i - 1] == 0 and flowerbed[i + 1] == 0:
                flowerbed[i] = 1
                n -= 1
        # Return true if we managed to place at least n flowers
        return n <= 0

